   ident=f'p13-{family}-b{block}-{arm}';c,source=config(family,branch,split='heldout',gap=gap);f=out/'cases'/(ident+'.json');write(f,c);batch.append({'id':ident,'family':family,'block':block,'phase':1,'branch':branch,'arm':arm,'gap_s':gap,'sim_seed':seed,'kind':'p5_gap','condition':'p11-case','treatment':'P11-Z','config':'config/p13-formal-cases/'+f.name,'config_sha256':sha(f),'source_id':source['id'],'source_config_sha256':source['config_sha256'],'cohort':'P13_new66_fixed_cruise6s','question':'randomized interval-to-residual-COM-W/L/history and complete B/tail/repair total effects'})
